              "html": "A quantifier indicates the amount or quantity of a noun. When a تَأْكِيْدٌ مَعْنَوِيٌّ is used as a quantifier, it indicates the number of members or parts of something — as in 'I saw all the students' or 'I read the rest of the book'.",
